const probeText=String.raw`PASTE_THE_EXACT_LAB_5_FFPROBE_JSON_HERE`;
const captionsText=String.raw`PASTE_THE_EXACT_LAB_3_CAPTIONS_VTT_HERE`;
const manifestCsvText=String.raw`PASTE_THE_EXACT_LAB_4_ASSET_MANIFEST_CSV_HERE`;
if([probeText,captionsText,manifestCsvText].some(x=>x.startsWith('PASTE_'))) throw new Error('Paste exact prior checkpoint evidence into all three constants.');
return [{json:{run_id:'HB-001',probe:JSON.parse(probeText),captionsText,manifestCsvText,owner_approval_status:'pending'}}];

const x=$input.first().json; const f=[]; const v=x.probe.streams?.find(s=>s.codec_type==='video'); const a=x.probe.streams?.find(s=>s.codec_type==='audio'); const sub=x.probe.streams?.find(s=>s.codec_type==='subtitle'); const duration=Number(x.probe.format?.duration);
if(!v||v.codec_name!=='h264'||v.width!==1080||v.height!==1920||v.r_frame_rate!=='30/1'||v.pix_fmt!=='yuv420p') f.push({issue_id:'RV-TECH',category:'technical',severity:'blocking',evidence:'ffprobe mismatch',required_action:'repair render'});
if(!Number.isFinite(duration)||duration<28||duration>32) f.push({issue_id:'RV-DURATION',category:'technical',severity:'blocking',evidence:`duration=${duration}`,required_action:'render between 28 and 32 seconds'});
if(!a) f.push({issue_id:'RV-AUDIO',category:'audio',severity:'blocking',evidence:'no audio stream',required_action:'mux narration'}); if(!sub) f.push({issue_id:'RV-CAPTION-TRACK',category:'accessibility',severity:'blocking',evidence:'no muxed caption stream',required_action:'mux captions'});
const parseTime=t=>{const m=t.match(/^(\d{2}):(\d{2}):(\d{2})\.(\d{3})$/); return m?Number(m[1])*3600+Number(m[2])*60+Number(m[3])+Number(m[4])/1000:NaN;}; const cueLines=x.captionsText.split(/\r?\n/).filter(line=>line.includes(' --> ')); let previousEnd=0,captionValid=x.captionsText.startsWith('WEBVTT')&&cueLines.length===5; for(const line of cueLines){const parts=line.split(' --> '),start=parseTime(parts[0]),end=parseTime(parts[1]); if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start||Math.abs(start-previousEnd)>0.001) captionValid=false; previousEnd=end;} if(Math.abs(previousEnd-duration)>0.25) captionValid=false; if(!captionValid) f.push({issue_id:'RV-CAPTION',category:'accessibility',severity:'blocking',evidence:`cues=${cueLines.length}; last_end=${previousEnd}; duration=${duration}`,required_action:'repair ordered positive contiguous VTT cues'});
const lines=x.manifestCsvText.trim().split(/\r?\n/); const headers=lines[0].split(','); const rows=lines.slice(1).map(line=>Object.fromEntries(line.split(',').map((v,i)=>[headers[i],v]))); if(rows.length<7||rows.some(r=>!r.asset_id||!r.source_path||r.rights_status!=='approved_for_course_use'||r.status!=='accepted')) f.push({issue_id:'RV-RIGHTS',category:'rights',severity:'blocking',evidence:'manifest row incomplete or unapproved',required_action:'repair manifest and rights evidence'});
return [{json:{run_id:x.run_id,review_status:f.length?'blocked':'review_clear',findings:f,probe_version:'ffprobe-v1',duration_seconds:duration,caption_cue_count:cueLines.length,caption_timeline_valid:captionValid,manifest_rows:rows.length,owner_approval_status:'pending',requires_human_preview:true,release_allowed:false,external_action_count:0}}];
